import itertools, time
from scipy.optimize import least_squares
y=dv_dt
V={'t':t,'x':x,'v':v}
fn={'exp-':lambda u,e:np.exp(-e*u),'pow':lambda u,e:u**e,'inv1p':lambda u,e:1/(1+e*u),'sin':lambda u,e:np.sin(e*u)}
types=[(a_,fa,b_,fb) for a_,b_ in itertools.permutations('txv',2) for fa in fn for fb in fn]
def term(tp,e1,e2):
    a_,fa,b_,fb=tp
    return fn[fa](V[a_],e1)*fn[fb](V[b_],e2)
rng=np.random.default_rng(5)
t0=time.time()
def fit(extra_types,base_extra=None,nstart=3):
    out=[]
    for tp in extra_types:
        best=None
        for s in range(nstart):
            q0=np.r_[1.7,50,23,0.5,abs(rng.uniform(0.2,2)),abs(rng.uniform(0.2,2))]
            if base_extra is not None: q0=np.r_[q0[:3],base_extra[0],base_extra[1],base_extra[2],q0[3:]][:0] if False else q0
            def f(p):
                m=p[0]*t+p[1]/(1+p[2]*x)/v+p[3]*term(tp,p[4],p[5])
